#!/usr/bin/env Rscript
# =============================================================================
# Description
#   Compile final GWAS figure assemblies from completed GCTA MLMA-LOCO plot
#   components.
#
# Inputs
#   Component GWAS plot files under gcta_mlma_loco/
#
# Outputs
#   Final assembled GWAS figure files generated by the helper script.
# =============================================================================

# =============================================================================
# Configuration
# =============================================================================

script_path <- normalizePath(sub("--file=", "", grep("^--file=", commandArgs(FALSE), value = TRUE)[1]), mustWork = TRUE)
script_dir <- dirname(script_path)
root <- normalizePath(file.path(script_dir, "..", ".."), mustWork = TRUE)
helper <- file.path(script_dir, "helpers", "gwas_compile_final_figures.R")


# =============================================================================
# Functions
# =============================================================================

run_helper <- function() {
  old_wd <- getwd()
  on.exit(setwd(old_wd), add = TRUE)
  setwd(root)
  source(helper, local = FALSE)
}


# =============================================================================
# Main block
# =============================================================================

run_helper()

